function formatValidationErrors(errors) {
  if (!errors || errors.length === 0) return "Invalid input";
  return errors.map(err => {
    const propPath = err.dataPath ? err.dataPath.replace(/^\./, "") : "";
    if (err.keyword === "required") {
      const missing = err.params.missingProperty;
      const field = propPath ? `${propPath}.${missing}` : missing;
      return `Missing required property "${field}".`;
    }
    if (err.keyword === "type") {
      return `Property "${propPath}" must be of type ${err.params.type}.`;
    }
    if (err.keyword === "enum") {
      const allowed = Array.isArray(err.params.allowedValues) ? err.params.allowedValues.join(", ") : String(err.params.allowedValues);
      return `Property "${propPath}" must be one of: ${allowed}.`;
    }
    return propPath ? `Property "${propPath}" ${err.message}.` : (err.message ?? "Invalid input");
  }).join(" ");
}

const req = [{"keyword":"required","dataPath":"","schemaPath":"#/required","params":{"missingProperty":"location"},"message":"should have required property \x27location\x27"}];
console.log(formatValidationErrors(req));

